"""Source 2: Temporal contamination signal.

Compares model performance on pre-cutoff benchmark items (likely seen during
training) versus post-cutoff variants (unseen). A positive gap suggests the
model memorised pre-cutoff content.
"""

import numpy as np
import pandas as pd


def _item_scores_for_model(judgments: pd.DataFrame, model: str) -> pd.Series:
    """Per-item mean score for *model* (same logic as performance_gap)."""
    parts = []
    mask_a = judgments["model_a"] == model
    if mask_a.any():
        parts.append(
            judgments.loc[mask_a, ["item_id", "score_a"]]
            .rename(columns={"score_a": "score"})
        )
    mask_b = judgments["model_b"] == model
    if mask_b.any():
        parts.append(
            judgments.loc[mask_b, ["item_id", "score_b"]]
            .rename(columns={"score_b": "score"})
        )
    if not parts:
        return pd.Series(dtype=float)
    return pd.concat(parts, ignore_index=True).groupby("item_id")["score"].mean()


def compute_temporal_signal(
    judgments: pd.DataFrame,
    item_metadata: pd.DataFrame,
    models: list[str],
) -> pd.DataFrame:
    """Compute per-item temporal gap.

    Args:
        judgments: Pairwise judgments (same schema as Source 1).
        item_metadata: Must include columns
            [item_id, original_item_id, variant_type, temporal_tag].
            temporal_tag: "pre_cutoff" | "post_cutoff" | NaN.
        models: Models to average the temporal gap across.

    Returns:
        DataFrame [item_id, temporal_gap] where item_id is the original id.
        Items without both pre- and post-cutoff variants get NaN.
    """
    pre = item_metadata[item_metadata["temporal_tag"] == "pre_cutoff"]
    post = item_metadata[item_metadata["temporal_tag"] == "post_cutoff"]

    pre_map: dict[str, str] = dict(
        zip(pre["original_item_id"], pre["item_id"])
    )
    post_map: dict[str, str] = dict(
        zip(post["original_item_id"], post["item_id"])
    )
    common_originals = set(pre_map.keys()) & set(post_map.keys())

    if not common_originals:
        orig_ids = item_metadata["original_item_id"].dropna().unique()
        return pd.DataFrame(
            {"item_id": orig_ids, "temporal_gap": np.nan}
        )

    records: list[dict] = []
    for model in models:
        scores = _item_scores_for_model(judgments, model)
        if scores.empty:
            continue
        for orig_id in common_originals:
            pre_score = scores.get(pre_map[orig_id], np.nan)
            post_score = scores.get(post_map[orig_id], np.nan)
            if np.isnan(pre_score) or np.isnan(post_score):
                continue
            records.append(
                {"item_id": orig_id, "model": model, "gap": pre_score - post_score}
            )

    all_orig = (
        item_metadata["original_item_id"].dropna().unique()
        if "original_item_id" in item_metadata.columns
        else item_metadata["item_id"].unique()
    )

    if not records:
        return pd.DataFrame({"item_id": all_orig, "temporal_gap": np.nan})

    df = pd.DataFrame(records)
    agg = df.groupby("item_id")["gap"].mean().reset_index()
    agg.columns = ["item_id", "temporal_gap"]

    result = pd.DataFrame({"item_id": all_orig})
    result = result.merge(agg, on="item_id", how="left")
    return result
